﻿#Requires -Version 5.1
<#
.SYNOPSIS
  Start Multica Computer daemon: kill existing process first, then auto-restart on exit.

.EXAMPLE
  .\start-multica-daemon.ps1
  .\start-multica-daemon.ps1 -Once
  .\start-multica-daemon.ps1 -CheckIntervalSec 15
#>
[CmdletBinding()]
param(
    [switch]$Once,
    [ValidateRange(5, 3600)]
    [int]$CheckIntervalSec = 10,
    [ValidateRange(0, 100)]
    [int]$MaxStartFailures = 0,
    [string]$MulticaPath = ""
)

$ErrorActionPreference = "Continue"
try {
    [Console]::OutputEncoding = [System.Text.Encoding]::UTF8
} catch {}

function Write-Log {
    param(
        [string]$Message,
        [ValidateSet("INFO", "WARN", "ERROR")]
        [string]$Level = "INFO"
    )
    $line = "[{0}] [{1}] {2}" -f (Get-Date -Format "yyyy-MM-dd HH:mm:ss"), $Level, $Message
    Write-Host $line
    try {
        Add-Content -LiteralPath $script:LogFile -Value $line -Encoding UTF8
    } catch {}
}

function Resolve-MulticaExe {
    param([string]$Explicit)

    if ($Explicit) {
        if (-not (Test-Path -LiteralPath $Explicit)) {
            throw "MulticaPath not found: $Explicit"
        }
        return (Resolve-Path -LiteralPath $Explicit).Path
    }

    $candidates = @(
        (Join-Path $env:USERPROFILE '.multica\bin\multica.exe'),
        (Join-Path $PSScriptRoot 'multica-windows-amd64.exe'),
        (Join-Path $PSScriptRoot 'multica.exe')
    )

    foreach ($c in $candidates) {
        if ($c -and (Test-Path -LiteralPath $c)) {
            return (Resolve-Path -LiteralPath $c).Path
        }
    }

    $fromPath = Get-Command multica -ErrorAction SilentlyContinue
    if ($fromPath) {
        return $fromPath.Source
    }

    throw "multica.exe not found. Install to %USERPROFILE%\.multica\bin or place binary next to this script."
}

function Get-ServiceMetaPaths {
    $root = Join-Path $env:USERPROFILE '.multica\computer\run'
    return @{
        PidFile   = Join-Path $root 'service.pid'
        StateFile = Join-Path $root 'service.state.json'
    }
}

function Get-RecordedDaemonPid {
    $meta = Get-ServiceMetaPaths
    $list = New-Object System.Collections.Generic.List[int]

    if (Test-Path -LiteralPath $meta.PidFile) {
        $raw = (Get-Content -LiteralPath $meta.PidFile -Raw -ErrorAction SilentlyContinue)
        if ($null -ne $raw) {
            $raw = $raw.Trim()
            if ($raw -match '^\d+$') {
                [void]$list.Add([int]$raw)
            }
        }
    }

    if (Test-Path -LiteralPath $meta.StateFile) {
        try {
            $state = Get-Content -LiteralPath $meta.StateFile -Raw -Encoding UTF8 | ConvertFrom-Json
            if ($state.pid) {
                [void]$list.Add([int]$state.pid)
            }
        } catch {}
    }

    return @($list | Select-Object -Unique)
}

function Test-ProcessAlive {
    param([int]$ProcessId)
    if ($ProcessId -le 0) { return $false }
    try {
        $null = Get-Process -Id $ProcessId -ErrorAction Stop
        return $true
    } catch {
        return $false
    }
}

function Get-MulticaDaemonProcesses {
    Get-Process -Name 'multica','multica-windows-amd64' -ErrorAction SilentlyContinue |
        Where-Object {
            $_.Path -and (
                $_.Path -like '*\.multica\bin\multica.exe' -or
                $_.Path -like '*\multica-windows-amd64.exe'
            )
        }
}

function Test-DaemonRunning {
    param([string]$Exe)

    foreach ($pidValue in (Get-RecordedDaemonPid)) {
        if (Test-ProcessAlive -ProcessId $pidValue) {
            return $true
        }
    }

    if (Get-MulticaDaemonProcesses) {
        return $true
    }

    try {
        $out = & $Exe computer status 2>&1 | Out-String
        if ($out -match '(?m)^Computer:\s+running\b') {
            return $true
        }
    } catch {}

    return $false
}

function Stop-MulticaDaemon {
    param([string]$Exe)

    Write-Log "Stopping existing Computer daemon..."

    try {
        $prevEap = $ErrorActionPreference
        $ErrorActionPreference = 'SilentlyContinue'
        $stopLines = & $Exe computer stop 2>&1 | ForEach-Object { "$_" }
        $ErrorActionPreference = $prevEap
        $stopLines | Where-Object { $_ -and $_.Trim() -and ($_ -notmatch 'CategoryInfo|FullyQualifiedErrorId|所在位置|\+ ') } | ForEach-Object {
            Write-Log ("stop: {0}" -f $_)
        }
    } catch {
        Write-Log ("computer stop error: {0}" -f $_.Exception.Message) "WARN"
    }

    Start-Sleep -Seconds 1

    $targets = New-Object System.Collections.Generic.List[int]
    foreach ($pidValue in (Get-RecordedDaemonPid)) {
        if (Test-ProcessAlive -ProcessId $pidValue) {
            [void]$targets.Add($pidValue)
        }
    }
    foreach ($p in (Get-MulticaDaemonProcesses)) {
        if (-not $targets.Contains($p.Id)) {
            [void]$targets.Add($p.Id)
        }
    }

    foreach ($pidValue in $targets) {
        Write-Log ("Force-killing leftover PID={0}" -f $pidValue) "WARN"
        try {
            Stop-Process -Id $pidValue -Force -ErrorAction Stop
        } catch {
            Write-Log ("Kill PID={0} failed: {1}" -f $pidValue, $_.Exception.Message) "WARN"
        }
    }

    Start-Sleep -Seconds 1

    if (Test-DaemonRunning -Exe $Exe) {
        throw "Daemon still running after cleanup."
    }

    Write-Log "Old daemon cleaned up."
}

function Start-MulticaDaemon {
    param([string]$Exe)

    Write-Log "Starting Computer daemon..."
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'SilentlyContinue'
    $lines = & $Exe computer start 2>&1 | ForEach-Object { "$_" }
    $ErrorActionPreference = $prevEap
    $lines | Where-Object { $_ -and $_.Trim() -and ($_ -notmatch 'CategoryInfo|FullyQualifiedErrorId|所在位置|\+ ') } | ForEach-Object {
        Write-Log ("start: {0}" -f $_)
    }

    for ($i = 0; $i -lt 15; $i++) {
        Start-Sleep -Seconds 1
        if (Test-DaemonRunning -Exe $Exe) {
            $status = & $Exe computer status 2>&1 | Out-String
            $status -split "`r?`n" | Where-Object { $_.Trim() } | ForEach-Object {
                Write-Log ("status: {0}" -f $_)
            }
            Write-Log "Computer daemon is running."
            return
        }
    }

    throw "Daemon did not reach running state after start."
}

$script:LogDir = Join-Path $env:USERPROFILE '.multica\computer\logs'
New-Item -ItemType Directory -Force -Path $script:LogDir | Out-Null
$script:LogFile = Join-Path $script:LogDir ("daemon-watchdog-{0}.log" -f (Get-Date -Format "yyyyMMdd"))

$exe = Resolve-MulticaExe -Explicit $MulticaPath
Write-Log ("Using binary: {0}" -f $exe)
$mode = if ($Once) { "Once" } else { "Watchdog" }
Write-Log ("Mode={0}; CheckIntervalSec={1}; MaxStartFailures={2}" -f $mode, $CheckIntervalSec, $MaxStartFailures)

$startFailures = 0

while ($true) {
    try {
        if (Test-DaemonRunning -Exe $exe) {
            Stop-MulticaDaemon -Exe $exe
        } else {
            Write-Log "No running daemon detected."
        }

        Start-MulticaDaemon -Exe $exe
        $startFailures = 0
    } catch {
        $startFailures++
        Write-Log ("Start failed ({0}): {1}" -f $startFailures, $_.Exception.Message) "ERROR"
        if ($Once) { exit 1 }
        if ($MaxStartFailures -gt 0 -and $startFailures -ge $MaxStartFailures) {
            Write-Log ("Too many start failures ({0}), exiting." -f $MaxStartFailures) "ERROR"
            exit 1
        }
        Start-Sleep -Seconds $CheckIntervalSec
        continue
    }

    if ($Once) {
        Write-Log "Once mode: started successfully, exiting."
        exit 0
    }

    Write-Log ("Watchdog loop: checking every {0}s..." -f $CheckIntervalSec)
    while ($true) {
        Start-Sleep -Seconds $CheckIntervalSec
        if (-not (Test-DaemonRunning -Exe $exe)) {
            Write-Log "Daemon exited; auto-restarting..." "WARN"
            break
        }
    }
}

